<?php
session_start();require_once('dbstring.php');require_once('parent-utils.php');require_once('student-attendance-utils.php');parent_portal_ensure_tables($con);$parent=parent_portal_require_login($con);ensure_student_attendance_tables($con);
$parentId=mysqli_real_escape_string($con,$parent['parentid']);
$children=mysqli_query($con,"SELECT su.userid,su.firstname,su.othernames,su.surname,su.nextofkin_fullname,ce.class_name,bh.batch,
    (SELECT COUNT(*) FROM tblstudentattendanceentry ae INNER JOIN tblstudentattendancesession assn ON assn.sessionid=ae.sessionid WHERE ae.userid=su.userid AND assn.attendancedate>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) AND ae.attendancestatus IN ('absent','late')) AS attentiondays
    FROM tblparentstudentlink pl INNER JOIN tblsystemuser su ON su.userid=pl.studentid LEFT JOIN tblclass cl ON cl.userid=su.userid AND cl.status='active' LEFT JOIN tblclassentry ce ON ce.class_entryid=cl.class_entryid LEFT JOIN tblbatch bh ON bh.batchid=cl.batchid
    WHERE pl.parentid='$parentId' AND pl.status='active' AND su.systemtype='Student' ORDER BY su.firstname,su.surname");
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Children | Parent Portal</title><style>:root{--navy:#163656;--green:#08766f;--paper:#f3f7fa;--line:#d7e2ea}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:#1d3042;font:15px Arial,sans-serif}.wrap{max-width:1050px;margin:auto;padding:34px 18px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:26px 30px;border-radius:18px;background:linear-gradient(120deg,var(--navy),var(--green));color:#fff}.top h1{font:600 31px Georgia,serif;margin:3px 0}.top p{margin:0;color:#dcecf0}.top a{color:#fff;font-weight:bold}.notice{margin:18px 0;padding:14px;border:1px solid #b9dfd9;border-radius:10px;background:#edf9f6;color:#175b53}.children{display:grid;grid-template-columns:repeat(auto-fit,minmax(265px,1fr));gap:17px;margin-top:20px}.child{background:#fff;border:1px solid var(--line);border-radius:14px;padding:21px}.child h2{margin:0;color:var(--navy);font:600 24px Georgia,serif}.class{display:block;margin-top:7px;color:#537187}.stat{margin-top:18px;padding:13px;background:#f2f7f8;border-radius:9px}.stat b{display:block;font-size:25px;color:var(--green)}.privacy{margin-top:24px;color:#64748b;font-size:13px;line-height:1.55}@media(max-width:600px){.wrap{padding:18px 12px}.top{padding:22px;align-items:flex-start;flex-direction:column}}</style></head><body><main class="wrap"><header class="top"><div><p>Awuah Preparatory School</p><h1>Welcome, <?php echo parent_portal_safe($parent['fullname']);?></h1><p>Your approved children and recent school updates.</p></div><a href="parent-portal.php?logout=1">Sign out</a></header><?php if(!$children||mysqli_num_rows($children)===0){?><p class="notice">Your Parent Portal account is active, but no child link has been approved yet. Please contact the school office if you need help.</p><?php }else{?><section class="children"><?php while($child=mysqli_fetch_assoc($children)){$name=trim($child['firstname'].' '.$child['othernames'].' '.$child['surname']);?><article class="child"><h2><?php echo parent_portal_safe($name);?></h2><span class="class"><?php echo parent_portal_safe($child['class_name']?:'Class assignment pending'); ?><?php echo $child['batch']?' · '.parent_portal_safe($child['batch']):'';?></span><div class="stat"><small>Attendance attention in the last 30 days</small><b><?php echo (int)$child['attentiondays']; ?></b><small>Late or absent entries recorded by the school.</small></div></article><?php }?></section><?php }?><p class="privacy">For child safety, this portal shows only records linked and approved by the school. Contact the school office to correct a guardian contact or request an additional child link.</p></main></body></html>
